import { z } from "zod";

/** Current serialized document schema version. */
export const CURRENT_SCHEMA_VERSION = "1.0.0" as const;
/** Current semantic model version. */
export const CURRENT_SEMANTIC_MODEL_VERSION = "1.0.0" as const;

const IdentifierSchema = z
  .string()
  .min(1)
  .max(512)
  .regex(
    /^[A-Za-z][A-Za-z0-9._~:/#-]*$/,
    "Identifier must begin with a letter and contain only stable URI/name-safe characters",
  );

const LocalNameSchema = z
  .string()
  .min(1)
  .max(256)
  .regex(/^[A-Za-z_][A-Za-z0-9._-]*$/, "Name must begin with a letter or underscore");

const QualifiedNameSchema = z
  .string()
  .min(3)
  .max(512)
  .regex(
    /^[A-Za-z_][A-Za-z0-9._-]*:[A-Za-z_][A-Za-z0-9._-]*$/,
    "Qualified name must have the form prefix:localName",
  );

const IriSchema = z
  .string()
  .min(3)
  .max(4096)
  .regex(/^[A-Za-z][A-Za-z0-9+.-]*:[^\s]*$/, "IRI must begin with a valid scheme followed by ':'");

const SemVerSchema = z
  .string()
  .regex(
    /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/,
    "Expected a semantic version",
  );

const IsoDateTimeSchema = z.string().datetime({ offset: true });
const IsoDateSchema = z.string().date();
const IsoTimeSchema = z.string().time();
const IsoDurationSchema = z.string().duration();
const IntegerLexemeSchema = z
  .string()
  .regex(/^-?(?:0|[1-9]\d*)$/, "Expected an arbitrary-precision integer lexeme");
const NonNegativeIntegerLexemeSchema = z
  .string()
  .regex(/^(?:0|[1-9]\d*)$/, "Expected a non-negative integer lexeme");
const PositiveIntegerLexemeSchema = z
  .string()
  .regex(/^[1-9]\d*$/, "Expected a positive integer lexeme");
const DecimalLexemeSchema = z
  .string()
  .regex(/^-?(?:0|[1-9]\d*)\.\d+$/, "Expected a non-exponent decimal lexeme");
const FloatLexemeSchema = z
  .string()
  .regex(
    /^(?:NaN|[+-]?Infinity|[+-]?(?:(?:0|[1-9]\d*)(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)$/,
    "Expected an IEEE-style floating-point lexical value",
  );

/**
 * Memoizes a recursive schema body. Zod 3 invokes a `z.lazy` getter on every
 * parse of the lazy node, which would rebuild the large discriminated unions
 * below once per formula, term, or type node in the document.
 */
const once = <T>(build: () => T): (() => T) => {
  let built: { value: T } | undefined;
  return () => {
    if (built === undefined) {
      built = { value: build() };
    }
    return built.value;
  };
};

/** A finite, JSON-safe value used only at explicit extension/interchange boundaries. */
export type JsonValue =
  null | boolean | string | number | readonly JsonValue[] | { readonly [key: string]: JsonValue };

const JsonValueSchemaBody = () =>
  z.union([
    z.null(),
    z.boolean(),
    z.string(),
    z.number().finite(),
    z.array(JsonValueSchema),
    z.record(z.string(), JsonValueSchema),
  ]);
export const JsonValueSchema: z.ZodType<JsonValue> = z.lazy(once(JsonValueSchemaBody));

export const ProbabilitySchema = z.number().finite().min(0).max(1);
export const TruthDegreeSchema = z.number().finite().min(0).max(1);
export const ConfidenceSchema = z.number().finite().min(0).max(1);
export const NonNegativeWeightSchema = z.number().finite().nonnegative();

const SourcePositionSchema = z
  .object({
    line: z.number().int().positive(),
    column: z.number().int().nonnegative(),
    offset: z.number().int().nonnegative().optional(),
  })
  .strict();

export const SourceLocationSchema = z
  .object({
    uri: IriSchema.optional(),
    start: SourcePositionSchema,
    end: SourcePositionSchema.optional(),
  })
  .strict()
  .superRefine((location, ctx) => {
    if (location.end !== undefined) {
      const startsAfterEnd =
        location.start.line > location.end.line ||
        (location.start.line === location.end.line && location.start.column > location.end.column);
      if (startsAfterEnd) {
        ctx.addIssue({
          code: "custom",
          path: ["end"],
          message: "Source location end must not precede start",
        });
      }
    }
  });

export const ExternalIdentifierSchema = z
  .object({
    system: z.string().min(1).max(256),
    value: z.string().min(1).max(2048),
    uri: IriSchema.optional(),
  })
  .strict();

export const AnnotationSchema = z
  .object({
    key: QualifiedNameSchema,
    value: JsonValueSchema,
    language: z.string().min(2).max(35).optional(),
    datatype: IriSchema.optional(),
  })
  .strict()
  .superRefine((annotation, ctx) => {
    if (annotation.language !== undefined && annotation.datatype !== undefined) {
      ctx.addIssue({
        code: "custom",
        path: ["datatype"],
        message: "An annotation cannot declare both language and datatype",
      });
    }
  });

export const ExtensionSchema = z
  .object({
    id: QualifiedNameSchema,
    version: SemVerSchema,
    payload: JsonValueSchema,
    schemaRef: IriSchema.optional(),
    semantics: z.string().min(1).max(4096),
    fallback: z
      .object({
        behavior: z.enum(["reject", "ignore", "preserve", "degrade"]),
        explanation: z.string().min(1).max(2048).optional(),
      })
      .strict()
      .optional(),
  })
  .strict();

export const ProvenanceLinkSchema = z
  .object({
    recordId: IdentifierSchema,
    role: z.enum([
      "source",
      "derived_from",
      "quoted_from",
      "generated_by",
      "validated_by",
      "reviewed_by",
      "asserted_by",
    ]),
    sourceFragment: z.string().min(1).max(4096).optional(),
  })
  .strict();

export const SemanticContextSchema = z
  .object({
    contextRefs: z.array(IdentifierSchema).min(1),
    composition: z.enum(["all", "any", "ordered_override"]),
  })
  .strict();

const NodeMetadataShape = {
  id: IdentifierSchema.optional(),
  label: z.string().min(1).max(512).optional(),
  description: z.string().min(1).max(8192).optional(),
  provenance: z.array(ProvenanceLinkSchema).optional(),
  annotations: z.array(AnnotationSchema).optional(),
  extensions: z.array(ExtensionSchema).optional(),
  semanticContext: SemanticContextSchema.optional(),
  sourceLocation: SourceLocationSchema.optional(),
  externalIdentifiers: z.array(ExternalIdentifierSchema).optional(),
} as const;

const NodeMetadataSchema = z.object(NodeMetadataShape).strict();

type NodeShape<Shape extends z.ZodRawShape> = Omit<typeof NodeMetadataShape, keyof Shape> & Shape;

/**
 * Builds a strict node schema: shared metadata fields plus node-specific
 * fields. Node-specific fields replace metadata fields of the same name at
 * both the runtime and the type level (e.g. a required `id`), which keeps
 * inference identical across Zod 3 and Zod 4.
 */
const node = <Shape extends z.ZodRawShape>(shape: Shape) => {
  const merged: Record<string, z.ZodTypeAny> = { ...NodeMetadataShape };
  for (const key of Object.keys(shape)) {
    merged[key] = shape[key] as z.ZodTypeAny;
  }
  return z.object(merged as NodeShape<Shape>).strict();
};

export type NodeMetadata = z.infer<typeof NodeMetadataSchema>;

export type Reference = z.infer<typeof ReferenceSchema>;

export const ReferenceSchema = node({
  kind: z.literal("reference"),
  targetId: IdentifierSchema,
  resolution: z.enum(["local", "imported", "external"]),
  targetFamily: z
    .enum([
      "node",
      "symbol",
      "type",
      "declaration",
      "statement",
      "rule",
      "constraint",
      "query",
      "proof",
      "context",
      "world",
      "agent",
      "jurisdiction",
      "organization",
      "environment",
      "security_domain",
      "assumption_set",
      "event",
      "action",
      "state",
      "argument",
      "process",
      "provenance",
      "module",
      "extension",
    ])
    .optional(),
  externalUri: IriSchema.optional(),
}).superRefine((reference, ctx) => {
  if (reference.resolution === "external" && reference.externalUri === undefined) {
    ctx.addIssue({
      code: "custom",
      path: ["externalUri"],
      message: "External references must declare externalUri",
    });
  }
  if (reference.resolution !== "external" && reference.externalUri !== undefined) {
    ctx.addIssue({
      code: "custom",
      path: ["externalUri"],
      message: "externalUri is only valid for external references",
    });
  }
});

export type VariableBinding = NodeMetadata & {
  readonly kind: "variable_binding";
  readonly name: string;
  readonly type?: TypeExpression;
  readonly domain?: ValueExpression;
  readonly variance?: "invariant" | "covariant" | "contravariant";
};

