export type ConceptExpression = NodeMetadata &
  (
    | { readonly kind: "concept_reference"; readonly concept: Reference }
    | { readonly kind: "top_concept" }
    | { readonly kind: "bottom_concept" }
    | { readonly kind: "concept_intersection"; readonly operands: readonly ConceptExpression[] }
    | { readonly kind: "concept_union"; readonly operands: readonly ConceptExpression[] }
    | { readonly kind: "concept_complement"; readonly operand: ConceptExpression }
    | {
        readonly kind: "object_some_values_from_concept";
        readonly property: Reference;
        readonly filler: ConceptExpression;
      }
    | {
        readonly kind: "object_all_values_from_concept";
        readonly property: Reference;
        readonly filler: ConceptExpression;
      }
    | {
        readonly kind: "object_has_value_concept";
        readonly property: Reference;
        readonly value: ValueExpression;
      }
    | { readonly kind: "object_has_self_concept"; readonly property: Reference }
    | {
        readonly kind: "object_cardinality_concept";
        readonly property: Reference;
        readonly restriction: CardinalityRestriction;
        readonly filler?: ConceptExpression;
      }
    | {
        readonly kind: "data_some_values_from_concept";
        readonly property: Reference;
        readonly datatype: TypeExpression;
      }
    | {
        readonly kind: "data_all_values_from_concept";
        readonly property: Reference;
        readonly datatype: TypeExpression;
      }
    | {
        readonly kind: "data_has_value_concept";
        readonly property: Reference;
        readonly value: ValueExpression;
      }
    | { readonly kind: "nominal_concept"; readonly individuals: readonly ValueExpression[] }
  );
export type CardinalityRestriction = z.infer<typeof CardinalityRestrictionSchema>;

