export const PrecisionSemanticsSchema = z
  .object({
    significantDigits: z.number().int().positive().optional(),
    decimalPlaces: z.number().int().nonnegative().optional(),
    exact: z.boolean().optional(),
  })
  .strict()
  .superRefine((precision, ctx) => {
    if (
      precision.significantDigits === undefined &&
      precision.decimalPlaces === undefined &&
      precision.exact === undefined
    ) {
      ctx.addIssue({
        code: "custom",
        message: "Precision semantics must specify at least one policy",
      });
    }
    if (precision.exact === true && precision.decimalPlaces !== undefined) {
      ctx.addIssue({
        code: "custom",
        path: ["decimalPlaces"],
        message: "Exact values cannot also request decimal-place rounding",
      });
    }
  });

export const RoundingSemanticsSchema = z
  .object({
    mode: z.enum([
      "toward_zero",
      "away_from_zero",
      "floor",
      "ceiling",
      "half_up",
      "half_down",
      "half_even",
      "half_away_from_zero",
    ]),
    decimalPlaces: z.number().int().nonnegative().optional(),
    significantDigits: z.number().int().positive().optional(),
  })
  .strict()
  .superRefine((rounding, ctx) => {
    if (rounding.decimalPlaces === undefined && rounding.significantDigits === undefined) {
      ctx.addIssue({
        code: "custom",
        message: "Rounding must specify decimalPlaces or significantDigits",
      });
    }
    if (rounding.decimalPlaces !== undefined && rounding.significantDigits !== undefined) {
      ctx.addIssue({
        code: "custom",
        path: ["significantDigits"],
        message: "Choose decimalPlaces or significantDigits, not both",
      });
    }
  });

export const UncertaintyIntervalSchema = z
  .object({
    lower: DecimalLexemeSchema,
    upper: DecimalLexemeSchema,
    confidenceLevel: ProbabilitySchema.optional(),
    interpretation: z.enum(["absolute", "relative", "credible_interval", "confidence_interval"]),
  })
  .strict()
  .superRefine((interval, ctx) => {
    const lower = Number(interval.lower);
    const upper = Number(interval.upper);
    if (Number.isFinite(lower) && Number.isFinite(upper) && lower > upper) {
      ctx.addIssue({
        code: "custom",
        path: ["upper"],
        message: "Uncertainty interval upper bound must not be below lower bound",
      });
    }
  });

export const TimeSemanticsSchema = z
  .object({
    clock: z.enum(["event_time", "processing_time", "ingestion_time", "logical_time"]),
    timeScale: z.enum(["utc", "tai", "gps", "local", "custom"]),
    zone: z.string().min(1).max(128).optional(),
    customScaleId: QualifiedNameSchema.optional(),
  })
  .strict()
  .superRefine((time, ctx) => {
    if (time.timeScale === "custom" && time.customScaleId === undefined) {
      ctx.addIssue({
        code: "custom",
        path: ["customScaleId"],
        message: "A custom time scale requires customScaleId",
      });
    }
    if (time.timeScale !== "custom" && time.customScaleId !== undefined) {
      ctx.addIssue({
        code: "custom",
        path: ["customScaleId"],
        message: "customScaleId is only valid for a custom time scale",
      });
    }
  });

export const TemporalBoundSchema = z
  .object({
    lower: IsoDurationSchema.optional(),
    upper: IsoDurationSchema.optional(),
    lowerInclusive: z.boolean().optional(),
    upperInclusive: z.boolean().optional(),
  })
  .strict()
  .superRefine((bound, ctx) => {
    if (bound.lower === undefined && bound.upper === undefined) {
      ctx.addIssue({
        code: "custom",
        message: "A temporal bound requires lower or upper",
      });
    }
  });

export const RecurrenceSchema = z
  .object({
    frequency: z.enum(["secondly", "minutely", "hourly", "daily", "weekly", "monthly", "yearly"]),
    interval: z.number().int().positive().optional(),
    count: z.number().int().positive().optional(),
    until: IsoDateTimeSchema.optional(),
    bySecond: z.array(z.number().int().min(0).max(59)).optional(),
    byMinute: z.array(z.number().int().min(0).max(59)).optional(),
    byHour: z.array(z.number().int().min(0).max(23)).optional(),
    byWeekday: z.array(z.enum(["MO", "TU", "WE", "TH", "FR", "SA", "SU"])).optional(),
    byMonthDay: z.array(z.number().int().min(-31).max(31)).optional(),
    byMonth: z.array(z.number().int().min(1).max(12)).optional(),
    weekStart: z.enum(["MO", "TU", "WE", "TH", "FR", "SA", "SU"]).optional(),
    exclusions: z.array(IsoDateTimeSchema).optional(),
  })
  .strict()
  .superRefine((recurrence, ctx) => {
    if (recurrence.count !== undefined && recurrence.until !== undefined) {
      ctx.addIssue({
        code: "custom",
        path: ["until"],
        message: "Recurrence count and until are mutually exclusive",
      });
    }
    if (recurrence.byMonthDay?.includes(0) === true) {
      ctx.addIssue({
        code: "custom",
        path: ["byMonthDay"],
        message: "Month-day zero is not valid",
      });
    }
  });

