export const CardinalityRestrictionSchema = z
  .object({
    minimum: NonNegativeIntegerLexemeSchema.optional(),
    maximum: NonNegativeIntegerLexemeSchema.optional(),
    exact: NonNegativeIntegerLexemeSchema.optional(),
  })
  .strict()
  .superRefine((restriction, ctx) => {
    if (
      restriction.minimum === undefined &&
      restriction.maximum === undefined &&
      restriction.exact === undefined
    ) {
      ctx.addIssue({
        code: "custom",
        message: "Cardinality restriction requires minimum, maximum, or exact",
      });
    }
    if (
      restriction.exact !== undefined &&
      (restriction.minimum !== undefined || restriction.maximum !== undefined)
    ) {
      ctx.addIssue({
        code: "custom",
        path: ["exact"],
        message: "Exact cardinality cannot be combined with minimum or maximum",
      });
    }
    if (
      restriction.minimum !== undefined &&
      restriction.maximum !== undefined &&
      BigInt(restriction.minimum) > BigInt(restriction.maximum)
    ) {
      ctx.addIssue({
        code: "custom",
        path: ["maximum"],
        message: "Maximum cardinality must not be below minimum cardinality",
      });
    }
  });

