export const DeclarationSchema: z.ZodType<Declaration> = z
  .discriminatedUnion("kind", [DeclarationArm_type_declaration, DeclarationArm_constant_declaration, DeclarationArm_function_declaration, DeclarationArm_predicate_declaration, DeclarationArm_proposition_declaration, DeclarationArm_relation_declaration, DeclarationArm_variable_declaration, DeclarationArm_unit_declaration, DeclarationArm_concept_declaration, DeclarationArm_individual_declaration, DeclarationArm_object_property_declaration, DeclarationArm_data_property_declaration, DeclarationArm_linguistic_variable_declaration, DeclarationArm_truth_domain_declaration, DeclarationArm_world_declaration, DeclarationArm_context_declaration, DeclarationArm_agent_declaration, DeclarationArm_jurisdiction_declaration, DeclarationArm_organization_declaration, DeclarationArm_environment_declaration, DeclarationArm_security_domain_declaration, DeclarationArm_assumption_set_declaration, DeclarationArm_event_declaration, DeclarationArm_action_declaration, DeclarationArm_state_declaration, DeclarationArm_accessibility_relation_declaration, DeclarationArm_causal_variable_declaration])
  .superRefine((declaration, ctx) => {
    if (
      declaration.kind === "function_declaration" ||
      declaration.kind === "predicate_declaration" ||
      declaration.kind === "relation_declaration"
    ) {
      const variadic =
        declaration.kind === "relation_declaration" ? false : declaration.variadic === true;
      const expected = declaration.parameters.length;
      if (
        (!variadic && declaration.arity !== expected) ||
        (variadic && declaration.arity > expected)
      ) {
        ctx.addIssue({
          code: "custom",
          path: ["arity"],
          message: variadic
            ? "Variadic arity is the number of required leading parameters and cannot exceed parameter count"
            : `Arity ${declaration.arity} does not match ${expected} parameters`,
        });
      }
      const variadicIndexes = declaration.parameters
        .map((parameter, index) => (parameter.variadic === true ? index : -1))
        .filter((index) => index >= 0);
      if (variadicIndexes.length > 1 || variadicIndexes.some((index) => index !== expected - 1)) {
        ctx.addIssue({
          code: "custom",
          path: ["parameters"],
          message: "At most one variadic parameter is allowed and it must be last",
        });
      }
    }
    if (declaration.kind === "unit_declaration") {
      if (
        declaration.baseUnit === undefined &&
        (declaration.multiplier !== undefined || declaration.offset !== undefined)
      ) {
        ctx.addIssue({
          code: "custom",
          path: ["baseUnit"],
          message: "Unit multiplier/offset requires a baseUnit",
        });
      }
    }
    if (declaration.kind === "action_declaration") {
      if (declaration.declarativeOnly && declaration.capability !== undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["capability"],
          message: "A declarative-only action cannot declare an executable capability",
        });
      }
      if (!declaration.declarativeOnly && declaration.capability === undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["capability"],
          message: "An executable action must declare a capability contract",
        });
      }
    }
    if (declaration.kind === "truth_domain_declaration") {
      const names = new Set(declaration.values.map((value) => value.name));
      declaration.designatedValues.forEach((name, index) => {
        if (!names.has(name)) {
          ctx.addIssue({
            code: "custom",
            path: ["designatedValues", index],
            message: `Designated truth value '${name}' is not declared`,
          });
        }
      });
    }
  });

