export const TemporalScopeSchema = z
  .object({
    start: IsoDateTimeSchema.optional(),
    end: IsoDateTimeSchema.optional(),
    startInclusive: z.boolean().optional(),
    endInclusive: z.boolean().optional(),
    recurrence: RecurrenceSchema.optional(),
  })
  .strict()
  .superRefine((scope, ctx) => {
    if (scope.start === undefined && scope.end === undefined && scope.recurrence === undefined) {
      ctx.addIssue({
        code: "custom",
        message: "Temporal scope requires start, end, or recurrence",
      });
    }
    if (
      scope.start !== undefined &&
      scope.end !== undefined &&
      Date.parse(scope.start) > Date.parse(scope.end)
    ) {
      ctx.addIssue({
        code: "custom",
        path: ["end"],
        message: "Temporal scope end must not precede start",
      });
    }
  });

export const SpatialScopeSchema = z
  .object({
    coordinateReferenceSystem: IriSchema,
    geometry: z.discriminatedUnion("kind", [
      z
        .object({
          kind: z.literal("point"),
          coordinates: z.tuple([z.number().finite(), z.number().finite()]),
        })
        .strict(),
      z
        .object({
          kind: z.literal("bounding_box"),
          minimum: z.tuple([z.number().finite(), z.number().finite()]),
          maximum: z.tuple([z.number().finite(), z.number().finite()]),
        })
        .strict(),
      z
        .object({
          kind: z.literal("named_region"),
          region: ReferenceSchema,
        })
        .strict(),
    ]),
  })
  .strict()
  .superRefine((scope, ctx) => {
    if (scope.geometry.kind === "bounding_box") {
      const [minX, minY] = scope.geometry.minimum;
      const [maxX, maxY] = scope.geometry.maximum;
      if (minX > maxX || minY > maxY) {
        ctx.addIssue({
          code: "custom",
          path: ["geometry", "maximum"],
          message: "Bounding-box maximum coordinates must not be below minimum coordinates",
        });
      }
    }
  });

