const RuleExceptionSchema = z.lazy(
  once(() =>
    node({
      kind: z.literal("rule_exception"),
      condition: FormulaSchema,
      behavior: z.enum([
        "disable_rule",
        "block_conclusion",
        "replace_conclusion",
        "lower_priority",
      ]),
      replacementHead: z.array(FormulaSchema).min(1).optional(),
      priorityDelta: z.number().int().optional(),
    }).superRefine((exception, ctx) => {
      if (exception.behavior === "replace_conclusion" && exception.replacementHead === undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["replacementHead"],
          message: "replace_conclusion requires replacementHead",
        });
      }
      if (exception.behavior !== "replace_conclusion" && exception.replacementHead !== undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["replacementHead"],
          message: "replacementHead is only valid for replace_conclusion",
        });
      }
      if (exception.behavior === "lower_priority" && exception.priorityDelta === undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["priorityDelta"],
          message: "lower_priority requires priorityDelta",
        });
      }
    }),
  ),
);

