/** Output type of RuleSchema, spelled as a union of its arms so each emitted declaration stays serializable (vendor-schema.ts). */
export type Rule =
  | z.infer<typeof RuleArm_strict_rule>
  | z.infer<typeof RuleArm_defeasible_rule>
  | z.infer<typeof RuleArm_default_rule>
  | z.infer<typeof RuleArm_horn_clause>
  | z.infer<typeof RuleArm_datalog_rule>
