/** Output type of ConstraintSchema, spelled as a union of its arms so each emitted declaration stays serializable (vendor-schema.ts). */
export type Constraint =
  | z.infer<typeof ConstraintArm_hard_constraint>
  | z.infer<typeof ConstraintArm_soft_constraint>
  | z.infer<typeof ConstraintArm_satisfiability_constraint>
  | z.infer<typeof ConstraintArm_optimization_objective>
  | z.infer<typeof ConstraintArm_weighted_constraint>
  | z.infer<typeof ConstraintArm_smt_constraint>
  | z.infer<typeof ConstraintArm_constraint_group>;

export const ConstraintSchema: z.ZodType<Constraint> = z
  .discriminatedUnion("kind", [ConstraintArm_hard_constraint, ConstraintArm_soft_constraint, ConstraintArm_satisfiability_constraint, ConstraintArm_optimization_objective, ConstraintArm_weighted_constraint, ConstraintArm_smt_constraint, ConstraintArm_constraint_group])
  .superRefine((constraint, ctx) => {
    if (constraint.kind === "soft_constraint") {
      if (constraint.penalty === "custom" && constraint.customPenalty === undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["customPenalty"],
          message: "A custom soft-constraint penalty requires customPenalty",
        });
      }
      if (constraint.penalty !== "custom" && constraint.customPenalty !== undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["customPenalty"],
          message: "customPenalty is only valid with a custom penalty",
        });
      }
    }
    if (constraint.kind === "smt_constraint") {
      if (constraint.logic === "custom" && constraint.customLogic === undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["customLogic"],
          message: "Custom SMT logic requires customLogic",
        });
      }
    }
    if (constraint.kind === "constraint_group") {
      const requiresCardinality = ["at_least", "at_most"].includes(constraint.combination);
      if (requiresCardinality && constraint.cardinality === undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["cardinality"],
          message: "at_least/at_most constraint groups require cardinality",
        });
      }
      if (!requiresCardinality && constraint.cardinality !== undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["cardinality"],
          message: "cardinality is only valid for at_least or at_most groups",
        });
      }
      constraint.members.forEach((member, index) => {
        if (member.targetFamily !== undefined && member.targetFamily !== "constraint") {
          ctx.addIssue({
            code: "custom",
            path: ["members", index, "targetFamily"],
            message: "Constraint-group members must target constraints",
          });
        }
        if (member.resolution === "local" && member.targetId === constraint.id) {
          ctx.addIssue({
            code: "custom",
            path: ["members", index, "targetId"],
            message: "A constraint group cannot contain itself",
          });
        }
      });
    }
  });

