export const InferenceStepSchema: z.ZodType<InferenceStep> = z
  .discriminatedUnion("kind", [InferenceStepArm_assumption_step, InferenceStepArm_modus_ponens_step, InferenceStepArm_modus_tollens_step, InferenceStepArm_universal_instantiation_step, InferenceStepArm_existential_instantiation_step, InferenceStepArm_resolution_step, InferenceStepArm_unification_step, InferenceStepArm_forward_chaining_step, InferenceStepArm_backward_chaining_step, InferenceStepArm_defeasible_application_step, InferenceStepArm_temporal_inference_step, InferenceStepArm_modal_inference_step, InferenceStepArm_bayesian_update_step, InferenceStepArm_fuzzy_inference_step, InferenceStepArm_causal_inference_step, InferenceStepArm_ontology_classification_step, InferenceStepArm_constraint_propagation_step, InferenceStepArm_policy_evaluation_step, InferenceStepArm_custom_inference_step])
  .superRefine((step, ctx) => {
    const ruleRequiredKinds = new Set([
      "forward_chaining_step",
      "backward_chaining_step",
      "defeasible_application_step",
      "policy_evaluation_step",
    ]);
    if (ruleRequiredKinds.has(step.kind) && (step.appliedRules?.length ?? 0) === 0) {
      ctx.addIssue({
        code: "custom",
        path: ["appliedRules"],
        message: `${step.kind} requires at least one applied rule reference`,
      });
    }
    if (step.kind === "bayesian_update_step") {
      const denominator = step.prior * step.likelihood;
      if (denominator === 0 && step.posterior !== 0) {
        ctx.addIssue({
          code: "custom",
          path: ["posterior"],
          message: "A zero prior-likelihood product cannot yield a non-zero posterior",
        });
      }
    }
  });

