export const ProofSchema: z.ZodType<Proof> = z
  .discriminatedUnion("kind", [ProofArm_proof_tree, ProofArm_derivation_graph, ProofArm_explanation_trace, ProofArm_counterexample])
  .superRefine((proof, ctx) => {
    if (proof.kind === "proof_tree") {
      const stepIds = new Set(proof.steps.map((step) => step.id));
      if (proof.rootStep.resolution === "local" && !stepIds.has(proof.rootStep.targetId)) {
        ctx.addIssue({
          code: "custom",
          path: ["rootStep", "targetId"],
          message: "Proof-tree rootStep must reference a step in this proof",
        });
      }
    }
    if (proof.kind === "derivation_graph") {
      const stepIds = new Set(proof.steps.map((step) => step.id));
      proof.edges.forEach((edge, index) => {
        if (edge.fromStep.resolution === "local" && !stepIds.has(edge.fromStep.targetId)) {
          ctx.addIssue({
            code: "custom",
            path: ["edges", index, "fromStep", "targetId"],
            message: "Derivation edge source must reference a step in this proof",
          });
        }
        if (edge.toStep.resolution === "local" && !stepIds.has(edge.toStep.targetId)) {
          ctx.addIssue({
            code: "custom",
            path: ["edges", index, "toStep", "targetId"],
            message: "Derivation edge target must reference a step in this proof",
          });
        }
      });
    }
  });

