export const ProcessModelSchema = node({
  kind: z.literal("process_model"),
  id: IdentifierSchema,
  name: z.string().min(1).max(512),
  elements: z.array(ProcessElementSchema).min(1),
  entryPoints: z.array(ReferenceSchema).min(1),
  terminalElements: z.array(ReferenceSchema).optional(),
  invariants: z.array(FormulaSchema).optional(),
  scope: ContextualScopeSchema.optional(),
}).superRefine((process, ctx) => {
  const elementIds = new Set(process.elements.map((element) => element.id));
  process.entryPoints.forEach((entry, index) => {
    if (entry.resolution === "local" && !elementIds.has(entry.targetId)) {
      ctx.addIssue({
        code: "custom",
        path: ["entryPoints", index, "targetId"],
        message: "Process entry point must reference an element in the process",
      });
    }
  });
  process.elements.forEach((element, elementIndex) => {
    if (element.kind === "concurrency") {
      const branchCount = element.branches.length;
      if (element.joinPolicy === "quorum") {
        if (element.quorum === undefined || element.quorum > branchCount) {
          ctx.addIssue({
            code: "custom",
            path: ["elements", elementIndex, "quorum"],
            message: "Quorum join requires a quorum no greater than branch count",
          });
        }
      } else if (element.quorum !== undefined) {
        ctx.addIssue({
          code: "custom",
          path: ["elements", elementIndex, "quorum"],
          message: "quorum is only valid for a quorum join policy",
        });
      }
    }
  });
});

