/**
 * Canonical root schema for complete logical knowledge-base documents.
 * Structural and cross-document semantic checks are both applied by parse().
 */
const LogicalKnowledgeBaseSemanticSchema = LogicalKnowledgeBaseBaseSchema.superRefine(
  (knowledgeBase, ctx) => {
    if (knowledgeBase.schemaVersion !== CURRENT_SCHEMA_VERSION) {
      ctx.addIssue({
        code: "custom",
        path: ["schemaVersion"],
        message: `Unsupported schemaVersion '${knowledgeBase.schemaVersion}'; expected '${CURRENT_SCHEMA_VERSION}' or migrate first`,
      });
    }
    if (
      knowledgeBase.createdAt !== undefined &&
      knowledgeBase.modifiedAt !== undefined &&
      Date.parse(knowledgeBase.createdAt) > Date.parse(knowledgeBase.modifiedAt)
    ) {
      ctx.addIssue({
        code: "custom",
        path: ["modifiedAt"],
        message: "modifiedAt must not precede createdAt",
      });
    }
    for (const issue of collectSemanticIssues(knowledgeBase)) {
      ctx.addIssue({
        code: "custom",
        path: [...issue.path],
        message: issue.message,
      });
    }
  },
);

/**
 * Canonical entry point for parsing and semantically validating a complete
 * logical knowledge-base document. Input is rejected unless it is JSON-safe,
 * structurally valid, reference-consistent, and semantically coherent.
 */
export const LogicalKnowledgeBaseSchema: z.ZodType<LogicalKnowledgeBase, unknown> = z.preprocess((input, ctx) => {
  const transportIssue = inspectRuntimeTransportSafety(input);
  if (transportIssue !== undefined) {
    ctx.addIssue({
      code: "custom",
      path: [...transportIssue.path],
      message: transportIssue.message,
      fatal: true,
    });
    return z.NEVER;
  }
  return input;
}, LogicalKnowledgeBaseSemanticSchema);

/** Complete parsed knowledge-base type inferred from the canonical root schema. */
export type LogicalKnowledgeBase = z.infer<typeof LogicalKnowledgeBaseSemanticSchema>;

export type SemanticIssue = {
  readonly path: readonly (string | number)[];
  readonly message: string;
};

export type ReferenceIndexEntry = {
  readonly id: string;
  readonly kind: string;
  readonly path: readonly (string | number)[];
};

/** Index of stable IDs and symbol declarations for downstream tooling. */
export type ReferenceIndex = {
  readonly byId: ReadonlyMap<string, ReferenceIndexEntry>;
  readonly symbolsByName: ReadonlyMap<string, ReferenceIndexEntry>;
  readonly rulesById: ReadonlyMap<string, ReferenceIndexEntry>;
};

type MutableIssue = {
  path: (string | number)[];
  message: string;
};

type NodeRecord = Record<string, unknown>;

function isRecord(value: unknown): value is NodeRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Returns true when `key` on `parent` holds opaque interchange data
 * (`JsonValue`) rather than logical nodes. Opaque subtrees are never indexed,
 * reference-checked, scope-checked, or reordered, so extension payloads may
 * freely use keys such as `id`, `kind`, or `provenance`.
 */
function isOpaqueChild(
  parent: NodeRecord,
  key: string,
  path: readonly (string | number)[],
): boolean {
  const collection = path.length >= 2 ? path[path.length - 2] : undefined;
  switch (key) {
    case "payload":
      return collection === "extensions" && "semantics" in parent;
    case "value":
      return (
        (collection === "annotations" && "key" in parent) ||
        (collection === "outcomes" && "probability" in parent)
      );
    case "parameters":
      return parent.kind === "custom_membership" || parent.kind === "custom_distribution";
    case "boundaryPayloadExample":
      return true;
    default:
      return false;
  }
}

/**
 * Depth-first walk over every logical node. The `path` handed to the visitor
 * is a shared, mutable buffer that is only valid during the visitor call;
 * visitors that retain it must copy it.
 */
function walkUnknown(
  value: unknown,
  path: (string | number)[],
  visitor: (record: NodeRecord, path: readonly (string | number)[]) => void,
): void {
  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index += 1) {
      path.push(index);
      walkUnknown(value[index], path, visitor);
      path.pop();
    }
    return;
  }
  if (!isRecord(value)) {
    return;
  }
  visitor(value, path);
  for (const key of Object.keys(value)) {
    if (isOpaqueChild(value, key, path)) {
      continue;
    }
    path.push(key);
    walkUnknown(value[key], path, visitor);
    path.pop();
  }
}

function kindOf(record: NodeRecord): string | undefined {
  return typeof record.kind === "string" ? record.kind : undefined;
}

function idOf(record: NodeRecord): string | undefined {
  return typeof record.id === "string" ? record.id : undefined;
}

function nearestCollectionField(path: readonly (string | number)[]): string | undefined {
  for (let index = path.length - 1; index >= 0; index -= 1) {
    const part = path[index];
    if (typeof part === "string") {
      return part;
    }
  }
  return undefined;
}

function indexedRecordKind(
  record: NodeRecord,
  path: readonly (string | number)[],
): string | undefined {
  const explicitKind = kindOf(record);
  if (explicitKind !== undefined) {
    return explicitKind;
  }
  if (idOf(record) === undefined) {
    return undefined;
  }
  const collection = nearestCollectionField(path);
  switch (collection) {
    case "extensions":
      // Root extensions form an addressable extension registry. Extensions
      // attached to individual nodes are metadata instances, not global nodes.
      return path.length === 2 ? "extension" : undefined;
    case "logicProfiles":
      return "logic_profile";
    case "inputs":
      return "identified_input";
    case "outputs":
      return "identified_output";
    case "rows":
      return "decision_row";
    case "transformationHistory":
      return "transformation_history_entry";
    case "entries":
      return "mapping_entry";
    case "appliedMigrations":
      return "migration_record";
    default:
      return "identified_record";
  }
}

function referenceFrom(value: unknown): NodeRecord | undefined {
  return isRecord(value) && value.kind === "reference" ? value : undefined;
}

function referenceTargetId(value: unknown): string | undefined {
  const reference = referenceFrom(value);
  return reference !== undefined && typeof reference.targetId === "string"
    ? reference.targetId
    : undefined;
}

